// PasswordService handles password hashing, comparison, and validation.
type PasswordService struct {
	cost int // bcrypt cost factor
}

// NewPasswordService creates a new PasswordService with default bcrypt cost.
func NewPasswordService() *PasswordService {
	return &PasswordService{cost: bcryptCost} // bcryptCost is defined in source
}

// HashPassword generates a bcrypt hash of the given password.
func (s *PasswordService) HashPassword(password string) (string, error) {
	bytes, err := bcrypt.GenerateFromPassword([]byte(password), s.cost)
	if err != nil {
		return "", err
	}
	return string(bytes), nil
}

// ComparePassword compares a hashed password with a plaintext password.
// Returns nil on success, or an error if they don't match.
func (s *PasswordService) ComparePassword(hashedPassword, password string) error {
	return bcrypt.CompareHashAndPassword([]byte(hashedPassword), []byte(password))
}

// DummyCompare performs a constant-time comparison against a dummy hash.
// Used to prevent timing attacks for non-existent users.
func (s *PasswordService) DummyCompare(password string) {
	_ = bcrypt.CompareHashAndPassword([]byte(dummyHash), []byte(password)) // dummyHash is pre-computed
}

// ValidatePasswordStrength checks for common password weaknesses.
func (s *PasswordService) ValidatePasswordStrength(password string) error {
	if len(password) < minPasswordLength { // minPasswordLength is 10
		return ErrPasswordTooShort
	}
	if commonPasswords[strings.ToLower(password)] { // commonPasswords map is in source
		return ErrPasswordCommon
	}

	// Simplified: full validation checks for uppercase, lowercase, number, special char
	var hasUpper, hasLower, hasNumber, hasSpecial bool
	for _, char := range password {
		if unicode.IsUpper(char) { hasUpper = true }
		if unicode.IsLower(char) { hasLower = true }
		if unicode.IsNumber(char) { hasNumber = true }
		if unicode.IsSymbol(char) || unicode.IsPunct(char) { hasSpecial = true }
	}

	if !hasUpper || !hasLower || !hasNumber || !hasSpecial {
		return ErrPasswordTooWeak
	}
	return nil
}

Password management services handle the hashing, comparison, and strength validation of user passwords. The PasswordService in backend/internal/auth/password.go uses bcrypt for hashing, providing a computationally intensive algorithm to resist brute-force attacks.

To prevent username enumeration attacks, which could allow an attacker to determine valid usernames by observing response times, a constant-time comparison mechanism is implemented. The DummyCompare function compares a password against a pre-computed hash, ensuring that password verification for both existing and non-existent users takes approximately the same amount of time.

Password strength is enforced through validation rules that check for minimum length, the presence of common or weak password patterns, and the inclusion of various character types (uppercase, lowercase, numbers, special characters). Errors for validation failures, such as ErrPasswordTooShort or ErrPasswordTooWeak, are explicitly defined to enable specific handling by calling functions.

