func (s *Service) NextInvoiceNumber(ctx context.Context) (string, error) {
	var result models.InvoiceCounter // Defines a struct to hold the counter value
	opts := options.FindOneAndUpdate().
		SetUpsert(true).           // Create the document if it doesn't exist
		SetReturnDocument(options.After) // Return the document after the update

	// Atomically increments the 'value' field of the invoice_number document
	err := s.db.Counters().FindOneAndUpdate(ctx,
		bson.M{"_id": "invoice_number"},
		bson.M{"$inc": bson.M{"value": 1}}, // Increment the value by 1
		opts,
	).Decode(&result)
	if err != nil {
		return "", fmt.Errorf("generate invoice number: %w", err)
	}

	// Formats the incremented value into a string like "INV-000001"
	return fmt.Sprintf("INV-%06d", result.Value), nil
}

The system generates sequential and formatted internal invoice numbers that are distinct from Stripe's own invoice IDs. This functionality is provided by the NextInvoiceNumber method within the Stripe integration service, which atomically increments a counter stored in the MongoDB Counters collection. The invoice numbers are formatted as "INV-XXXXXX". This mechanism ensures consistent, unique internal invoicing regardless of Stripe's invoice numbering.

