const api = axios.create({
  baseURL: '/api',
  headers: { 'Content-Type': 'application/json' },
});

/**
 * Sets or removes the Authorization header for all API requests.
 * @param token The access token, or null to remove the header.
 */
export function setAuthToken(token: string | null) {
  if (token) {
    api.defaults.headers.common['Authorization'] = `Bearer ${token}`;
  } else {
    delete api.defaults.headers.common['Authorization'];
  }
}

/**
 * Sets or removes the X-Tenant-ID header for all API requests.
 * @param tenantId The tenant ID, or null to remove the header.
 */
export function setTenantHeader(tenantId: string | null) {
  if (tenantId) {
    api.defaults.headers.common['X-Tenant-ID'] = tenantId;
  } else {
    delete api.defaults.headers.common['X-Tenant-ID'];
  }
}

// ... other API interceptors and client exports ...

The frontend application's API client centrally manages HTTP headers to facilitate secure, authenticated, and multi-tenant requests. The setAuthToken function in frontend/src/api/client.ts dynamically sets or removes the Authorization Bearer token header, which is essential for authenticating user sessions. Similarly, the setTenantHeader function, also in frontend/src/api/client.ts, manages the X-Tenant-ID header. This header is crucial for multi-tenant applications, ensuring that each API request is correctly routed and processed within the context of the active tenant. By managing these headers dynamically, the client ensures that all subsequent API calls automatically include the necessary authentication and tenant identification information.

